/* 🖼 ========================= Image ========================= */
.image {
  width: 75%;
  height: 290px;
  margin: 0 auto;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  border-radius: 25px;
  background: #000;
}

.image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

/* 📚 ====== Content Section ====== */
.content-section {
  display: flex;
  flex-direction: column;
  gap: 18px;
  margin-top: 15px;
  align-items: center;
}

/* 🪧 ====== Base Pair Card ====== */
.pair {
  border-radius: 6px;
  padding: 12px;
  text-align: center;
  font-family: "Roboto", "Noto Sans", sans-serif;
}

/* 🏮 ====== Word Styling ====== */
.word {
  font-size: 17px;
  color: #FB4141;          
  margin: 0 40px 1px 40px;
}


/* 📖 ====== Example Sentences ====== */
.example {
  font-size: 15px;
  font-weight: normal;
  color: inherit;
  margin: 0 40px;
  font-style: italic;
}

/* 🎧 ====== Audio Buttons ====== */
/* Hide default SVG icons */
.main-audio .replay-button svg,
.example-audio .replay-button svg {
  display: none;
}

/* Main Audio Button */
.main-audio .replay-button:before {
  content: '🎧( ˘͈ ᵕ ˘͈♡)Listen to me~ ｡⋆.✧˚🦄✨';
  display: inline-block;
  font-size: 20px;
  color: #B9375D;
  font-family: "Roboto", "Noto Sans", sans-serif;
  cursor: pointer;
  transition: transform 0.25s ease-in-out;
}
.main-audio .replay-button:hover:before {
  transform: scale(1.05);
}

/* Example Audio Button */
.example-audio .replay-button:before {
  content: "🎧";
  display: inline-block;
  font-size: 20px;
  color: #DB8DD0;
  cursor: pointer;
  transition: transform 0.25s ease-in-out;
}
.example-audio .replay-button:hover:before {
  transform: scale(1.05);
}

/* ✍️ ====== Type Answer Styling ====== */
.card, .card * {
  box-sizing: border-box;
}

/* Input Box */
.typeAnswer input[type="text"],
input#typeans,
input#typeanswer,
input[id^="type"] {
  width: 75% !important;
  max-width: 840px !important;
  margin: 16px auto 6px auto !important;
  display: block !important;
  text-align: center;
  padding: 15px !important;
  border-radius: 10px !important;
  border: 1px solid #FB4141 !important;
  background: rgba(255,255,255,0.06) !important;
  font-family: "Roboto", "Noto Sans", sans-serif;
  font-size: 20px !important;
  color: inherit;
  outline: none !important;
}
.typeAnswer input[type="text"]:focus {
  border-color: #FFCC66 !important;
  box-shadow: 0 0 14px #FFCC6688 !important;
}

/* Answer Feedback Colors */
#typeans .typeGood,
.typeAnswer .typeGood {
  color: #78C841 !important;  /* green */
  text-decoration: none !important;
  background: none !important;
  font-family: "Roboto", "Noto Sans", sans-serif;
  font-size: 17px;
}
#typeans .typeBad,
.typeAnswer .typeBad {
  color: #FF3F33 !important;  /* red */
  text-decoration: none !important;
  background: none !important;
  font-family: "Roboto", "Noto Sans", sans-serif;
  font-size: 17px;
}
#typeans .typeMissed,
.typeAnswer .typeMissed {
  color: #CA7842 !important;  /* orange */
  text-decoration: none !important;
  background: none !important;
  font-family: "Roboto", "Noto Sans", sans-serif;
  font-size: 17px;
}

/* Remove arrow completely */
.typearrow,
#typearrow {
  display: none !important;
}

/* Ensure answer display consistency */
#typeans,
#typeans * {
  font-family: "Roboto", "Noto Sans", sans-serif;
  font-size: 17px;
  background: none !important;
  color: inherit !important;
  line-height: 1.3 !important;
  margin-top: 4px !important;
  overflow-x: auto;
  white-space: nowrap;
}

/* 👀 ====== Show/Hide Toggle ====== */
/* Hide the checkbox */
.toggle-checkbox {
  display: none;
}

/* Button look */
.toggle-button {
  display: inline-block;
  padding: 3px 10px;
  background: linear-gradient(135deg, #FF3F7F, #A23FFF);
  border: transparent;
  border-radius: 12px;
  cursor: pointer;
  user-select: none;

  /* Font */
  font-family: "Poppins", "Inter", "Segoe UI", sans-serif;
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  margin: 0 40px;
}

/* Hover effect */
.toggle-button:hover {
  background: linear-gradient(135deg, #FF6FAF, #C04FFF);
}

/* Button text */
.toggle-button::before {
  content: "🐵 Show";
}
.toggle-checkbox:checked + .toggle-button::before {
  content: "🙈 Hide";
}

/* Hidden by default */
.toggle-content {
  display: none;
  margin-top: 10px;
}

/* Reveal on check */
.toggle-checkbox:checked ~ .toggle-content {
  display: block;
}



/* ======================= 🧭 Sidebar ======================= */
/* 🎀 Sidebar container */
.sidebar {
  position: fixed;
  top: 50px;
  right: 10px;
  width: 220px;
	height: 400px;
	overflow-y: auto;
  background: #fffafc;
  border: 1.5px solid #E69AB2;
  border-radius: 16px;
  padding: 8px 10px;
  transition: all 0.25s ease;
  display: none;
  z-index: 9999;
}

/* When open */
.sidebar.open {
  display: block;
}

/* Title inside sidebar */
.sidebar h3 {
  font-size: 15px;
  color: #B9375D;
  margin: 12px 0 12px;
  font-weight: bold;
}

/* Scrollbar styling */
.sidebar::-webkit-scrollbar {
  width: 8px;
}
.sidebar::-webkit-scrollbar-thumb {
  background-color: #E69AB2;
  border-radius: 4px;
}
.sidebar::-webkit-scrollbar-track {
  background-color: #FCE4EC;
}

/* Checkbox labels */
.sidebar label {
  display: block;
  margin-bottom: 5px;
  font-size: 14px;
  text-align: left;
}

.sidebar label input[type="checkbox"] {
  margin-right: 6px;
  transform: scale(1.2);
  accent-color: #B9375D;
}

/* ⚙️ Button */
  .settings-btn {
    position: fixed;
    top: 10px;
    right: 10px;
    z-index: 1000;
    background: linear-gradient(135deg, #FF3F7F, #A23FFF);
    border: transparent;
  	border-radius: 6px;
    width: 40px;
    height: 40px;
    font-size: 18px;
    cursor: pointer;
    box-shadow: 0 2px 5px rgba(0,0,0,0.2);
  }

.settings-btn:hover {
  transform: scale(1.05);
	background: linear-gradient(135deg, #FF6FAF, #C04FFF)
}
